// initFromEndpoint verifies read access to one Argo CD instance and writes a
// profile for repository discovery (--pr), an explicit Application or the
// current Applications generated by an ApplicationSet. Without a selection it
// lists the readable Applications instead.
func initFromEndpoint(ctx context.Context, f *flag.FlagSet, o *initOptions, stdout, stderr io.Writer) int {
	if o.localChildren || o.namespaceProvided {
		fmt.Fprintln(stderr, "--local-children and --child-namespace require --connections")
		return domain.ExitInvalidConfiguration
	}
	if !profile.ValidEndpoint(o.endpoint) || (o.app != "" && o.set != "") || (o.prURL != "" && (o.app != "" || o.set != "")) {
		fmt.Fprintln(stderr, "Usage: diffaro init "+initEndpointArgs+" [--config NEW_FILE] [--single-instance]")
		return domain.ExitInvalidConfiguration
	}
	connection := profile.Instance{ID: o.instance, Endpoint: o.endpoint, TokenEnv: o.tokenEnv, LocalHelm: o.localHelm, HelmBinary: o.helmBinary, HelmEnvironment: o.helmEnvironment}
	repoServer, err := o.repoServerConnection()
	if err != nil {
		fmt.Fprintln(stderr, err.Error())
		return domain.ExitInvalidConfiguration
	}
	connection.RepoServer = repoServer
	credentialConfig := profile.Config{Git: profile.Git{TokenEnv: o.gitToken}, Instances: []profile.Instance{connection}}
	secrets, err := o.credentials.resolve(f, &credentialConfig)
	if err != nil {
		fmt.Fprintln(stderr, err.Error())
		return domain.ExitInvalidConfiguration
	}
	connection.Token = credentialConfig.Instances[0].Token
	if err := checkNewProfilePath(o.config); err != nil {
		fmt.Fprintln(stderr, err.Error())
		return domain.ExitInvalidConfiguration
	}
	client := &argocd.Client{Instance: o.instance, HTTP: httpx.NewWithTokenEnv(o.endpoint, connection.Token, credentialConfig.Instances[0].TokenEnv, 30*time.Second, o.limits.MaxResponseBytes)}
	e := endpointInit{f: f, o: o, connection: connection, client: client, redactor: security.Redactor{Secrets: secrets}, stdout: stdout, stderr: stderr}
	if o.prURL != "" {
		return e.discovery(ctx)
	}
	name := o.app
	if o.set != "" {
		name = o.set
	}
	if name == "" {
		return e.listApplications(ctx)
	}
	return e.selected(ctx, name)
}

// endpointInit is one verified init --endpoint connection.
type endpointInit struct {
	f              *flag.FlagSet
	o              *initOptions
	connection     profile.Instance // with the resolved token
	client         *argocd.Client
	redactor       security.Redactor
	stdout, stderr io.Writer
}

// discovery writes a repository-discovery profile for --pr after one
// readable Application list proves access.
func (e endpointInit) discovery(ctx context.Context) int {
	o := e.o
	c, err := onboarding.DiscoveryProfile(e.connection, o.prURL, o.gitAPI, o.gitToken, o.single)
	if err == nil {
		err = setDiscoveryOptions(&c, o)
	}
	if err != nil {
		return e.fail(err)
	}
	items, err := e.client.ListApplications(ctx, "", o.limits.MaxApplications)
	if err != nil {
		return e.fail(err)
	}
	// The list proved access; it also shows Applications that use the PR
	// repository through a host the new profile does not declare.
	declared := c
	setMirrorHosts(&declared, o)
	apps := make([]domain.Application, 0, len(items))
	for _, item := range items {
		apps = append(apps, item.Application)
	}
	hint := preview.OtherHostHint(preview.OtherHostSources(apps, declared.Git))
	if hint != "" && preview.RepositoryApplications(apps, declared.Git) == 0 {
		// The profile would select no Application, and every diff would
		// report no changes for it.
		fmt.Fprintln(e.stderr, "No profile written: no readable Application uses the PR repository under its URL or a declared alias or mirror host, so the profile would select none.")
		fmt.Fprintln(e.stderr, e.redactor.Text(hint))
		fmt.Fprintln(e.stderr, "Rerun init with that option.")
		return domain.ExitInvalidConfiguration
	}
	code := e.writeProfile(c, false)
	if code == domain.ExitSuccess && hint != "" {
		fmt.Fprintln(e.stderr, "Warning: "+e.redactor.Text(hint))
	}
	if code == domain.ExitSuccess && !e.connection.LocalHelm && e.connection.RepoServer == nil {
		if parents := appOfAppsParents(items, declared.Git); parents > 0 {
			// The Application API cannot freeze the branch another
			// repository's child tracks, nor render a changed child spec
			//.
			fmt.Fprintf(e.stderr, "Warning: %d Application(s) using the PR repository manage child Applications (App-of-Apps). With the Application API backend, a child that tracks a branch of another repository fails with revision_mapping_required, and a new or reconfigured child is skipped. Rerun init with --local-helm to analyze them.\n", parents)
		}
	}
	return code
}

// appOfAppsParents counts the Applications using the PR repository whose
// Argo CD status lists child Applications or ApplicationSets.
func appOfAppsParents(items []domain.OwnedApplication, git profile.Git) int {
	n := 0
	for _, item := range items {
		if item.ManagesApplications != nil && *item.ManagesApplications && preview.RepositoryApplications([]domain.Application{item.Application}, git) == 1 {
			n++
		}
	}
	return n
}

// listApplications prints the readable Applications to choose from and
// writes no profile.
func (e endpointInit) listApplications(ctx context.Context) int {
	items, err := e.client.ListApplications(ctx, "", e.o.limits.MaxApplications)
	if err != nil {
		return e.fail(err)
	}
	fmt.Fprintln(e.stdout, "Choose a readable Application with --application namespace/name, or its controller with --application-set namespace/name:")
	for _, item := range items {
		fmt.Fprintf(e.stdout, "- %s\n", e.redactor.Text(item.Application.ID.Namespace+"/"+item.Application.ID.Name))
	}
	return domain.ExitSuccess
}

// selected writes a profile for the explicit --application, or for the
// Applications the --application-set currently generates; every selected
// Application is read individually.
func (e endpointInit) selected(ctx context.Context, name string) int {
	o := e.o
	parts := strings.Split(name, "/")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		fmt.Fprintln(e.stderr, "selection must be namespace/name")
		return domain.ExitInvalidConfiguration
	}
	id := domain.ApplicationID{Instance: o.instance, Namespace: parts[0], Name: parts[1]}
	ids := []domain.ApplicationID{id}
	var selected *domain.ApplicationID
	if o.set != "" {
		c := profile.Config{ApplicationSets: []domain.ApplicationID{id}, Render: o.limits}
		resolved, _, _, issues := preview.SelectGenerated(ctx, c, map[string]domain.ApplicationInventory{o.instance: e.client})
		if len(issues) > 0 {
			return e.fail(&domain.Failure{Issue: issues[0]})
		}
		ids, selected = resolved.Applications, &id
	}
	var apps []domain.Application
	for _, aid := range ids {
		a, err := e.client.Application(ctx, aid)
		if err != nil {
			return e.fail(err)
		}
		apps = append(apps, a)
	}
	c, err := onboarding.Profile(e.connection, apps, selected, o.gitAPI, o.gitToken, o.single)
	if err != nil {
		return e.fail(err)
	}
	return e.writeProfile(c, selected != nil)
}

// writeProfile adds the render limits, mirror hosts and persisted
// credential settings, then writes the new profile.
func (e endpointInit) writeProfile(c profile.Config, generated bool) int {
	o := e.o
	c.Render = o.limits
	skipped := setMirrorHosts(&c, o)
	data, c, err := o.credentials.persist(e.f, c)
	if err != nil {
		return e.fail(err)
	}
	code := writeInitializedProfile(o.config, data, c, generated, o.single, o.prURL, e.stdout, e.stderr)
	if code == domain.ExitSuccess {
		for _, host := range skipped {
			fmt.Fprintf(e.stdout, "--mirror-host %s is already the repository host (git.repositoryURL %s); no mirror entry is needed.\n", e.redactor.Text(host), e.redactor.Text(c.Git.RepositoryURL))
		}
	}
	return code
}

// fail prints a redacted provider failure and returns its exit code: 5 for
// denied access, 6 for other provider failures and 4 for invalid input.
func (e endpointInit) fail(err error) int {
	var failure *domain.Failure
	if errors.As(err, &failure) {
		if failure.Issue.Code == domain.CodeAccessDenied {
			printDeniedSummary(e.stderr)
			printIssue(e.stderr, failure.Issue, e.redactor)
			return domain.ExitDenied
		}
		printIssue(e.stderr, failure.Issue, e.redactor)
		return domain.ExitFailed
	}
	fmt.Fprintln(e.stderr, e.redactor.Text(err.Error()))
	return domain.ExitInvalidConfiguration
}

// repoServerConnection builds the optional repo-server configuration from the
// render connection flags. It returns nil when no repo-server is requested.
func (o *initOptions) repoServerConnection() (*profile.RepoServer, error) {
	if o.localHelm && (o.repoAddress != "" || o.forward) {
		return nil, fmt.Errorf("--local-helm cannot be combined with repo-server connection options")
	}
	if o.forward && o.repoAddress != "" {
		return nil, fmt.Errorf("choose --repo-server or --repo-server-forward")
	}
	if o.repoAddress == "" && !o.forward {
		if o.kubeconfig != "" || o.kubeContext != "" || o.plain || o.ca != "" || o.grpcurl != "" || o.kubectl != "" {
			return nil, fmt.Errorf("render connection options require --repo-server or --repo-server-forward")
		}
		return nil, nil
	}
	if o.kubeconfig == "" || o.kubeContext == "" {
		return nil, fmt.Errorf("automatic render context requires --kubeconfig and --kube-context")
	}
	grpc, err := resolveTool(o.grpcurl, "grpcurl")
	if err != nil {
		return nil, fmt.Errorf("grpcurl executable unavailable; provide --grpcurl")
	}
	kube, err := resolveTool(o.kubectl, "kubectl")
	if err != nil {
		return nil, fmt.Errorf("kubectl executable unavailable; provide --kubectl")
	}
	kubeconfig, err := filepath.Abs(o.kubeconfig)
	if err != nil {
		return nil, fmt.Errorf("cannot resolve kubeconfig path")
	}
	caPath := o.ca
	if caPath != "" {
		caPath, err = filepath.Abs(caPath)
		if err != nil {
			return nil, fmt.Errorf("cannot resolve CA path")
		}
	}
	server := &profile.RepoServer{Address: o.repoAddress, GRPCURL: grpc, Plaintext: o.plain, CAFile: caPath, Kubernetes: &profile.KubernetesContext{Kubectl: kube, Kubeconfig: kubeconfig, Context: o.kubeContext, Namespace: o.argoNamespace}}
	if o.forward {
		server.PortForward = &profile.PortForward{Resource: o.forwardResource, Port: o.forwardPort}
	}
	return server, nil
}

// resolveTool returns the absolute path of an explicit executable or of the
// fallback name found on PATH.
func resolveTool(value, fallback string) (string, error) {
	if value == "" {
		var err error
		value, err = exec.LookPath(fallback)
		if err != nil {
			return "", err
		}
	}
	return filepath.Abs(value)
}
